    };

    /// <summary>The icons the Files tab's script draws, as markup by name.</summary>
    public static IReadOnlyDictionary<string, string> Markup(params string[] names) =>
        names.ToDictionary(n => n, n => Get(n).ToString()!);

    /// <summary>The icon, decorative: screen readers skip it, so give its button or link a name of its own.</summary>
    public static IHtmlContent Get(string name, string? css = null) => new HtmlString(
        $"""<svg class="icon{(css is null ? "" : " " + css)}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">{Paths[name]}</svg>""");

    /// <summary>The raw path data, for scripts that draw the same icons (the theme switch).</summary>
    public static string PathsOf(string name) => Paths[name];
}
